<?php
namespace Tests\Feature;
use App\Models\Goal;
use App\Models\Habit;
use App\Models\GoalReview;
use App\Models\Task;
use App\Models\User;
use App\Models\Workspace;
use App\Services\Identity;
use App\Services\GoalService;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class GoalHabitTest extends TestCase {
 use RefreshDatabase;
 private function login(User $u): static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version])->withoutVite();}
 private function payload(array $extra=[]): array{return array_merge(['title'=>'Learn infrastructure','horizon'=>'year','category'=>'career','target'=>100,'actual'=>25,'unit'=>'hours','status'=>'active','vision'=>'Build a meaningful career'],$extra);}
 private function goal(User $u,array $extra=[]): Goal{$g=new Goal($this->payload($extra));$g->workspace_id=Identity::personal($u)->id;$g->save();return $g;}
 private function habit(User $u): Habit{$h=new Habit(['title'=>'Read daily','start_date'=>'2026-11-20','timezone'=>'Asia/Dhaka','active'=>true]);$h->workspace_id=Identity::personal($u)->id;$h->save();return $h;}
 private function task(User $u): Task{$t=new Task(['title'=>'Study task','status'=>'completed','priority'=>'medium']);$t->workspace_id=Identity::personal($u)->id;$t->creator_id=$u->id;$t->save();return $t;}
 public function test_guests_denied(): void{$this->get('/goals')->assertRedirect('/login');$this->get('/habits')->assertRedirect('/login');}
 public function test_goal_crud_and_measured_progress(): void{$u=User::factory()->create();$this->login($u)->post('/goals',$this->payload())->assertRedirect();$g=Goal::firstOrFail();$this->assertSame(25,$g->progress());$this->get('/goals/'.$g->id)->assertOk()->assertSee('25%');$this->get('/goals/create')->assertOk();$this->get('/goals/'.$g->id.'/edit')->assertOk();$this->put('/goals/'.$g->id,$this->payload(['actual'=>125,'status'=>'completed']))->assertRedirect();$this->assertSame(100,$g->fresh()->progress());$this->delete('/goals/'.$g->id)->assertRedirect('/goals');$this->assertDatabaseMissing('goals',['id'=>$g->id]);}
 public function test_invalid_measurements_rejected(): void{$u=User::factory()->create();$this->login($u)->post('/goals',$this->payload(['target'=>0]))->assertSessionHasErrors('target');$this->post('/goals',$this->payload(['actual'=>-1]))->assertSessionHasErrors('actual');$this->assertSame(0,Goal::count());}
 public function test_milestones_complete_reopen_and_delete(): void{$u=User::factory()->create();$g=$this->goal($u);$this->login($u)->post('/goals/'.$g->id.'/milestones',['title'=>'First milestone'])->assertRedirect();$m=$g->milestones()->firstOrFail();$url='/goals/'.$g->id.'/milestones/'.$m->id;$this->patch($url,['completed'=>1])->assertRedirect();$this->assertNotNull($m->fresh()->completed_at);$this->patch($url,['completed'=>0])->assertRedirect();$this->assertNull($m->fresh()->completed_at);$this->delete($url)->assertRedirect();$this->assertSame(0,$g->milestones()->count());}
 public function test_task_link_is_idempotent_and_deleting_goal_preserves_task(): void{$u=User::factory()->create();$g=$this->goal($u);$t=$this->task($u);$this->login($u);for($i=0;$i<2;$i++)$this->post('/goals/'.$g->id.'/tasks',['task_id'=>$t->id])->assertRedirect();$this->assertSame(1,$g->tasks()->count());$this->get('/goals/reports')->assertOk()->assertSee('Tasks 1/1');$this->delete('/goals/'.$g->id.'/tasks/'.$t->id)->assertRedirect();$this->assertSame(0,$g->tasks()->count());$this->post('/goals/'.$g->id.'/tasks',['task_id'=>$t->id])->assertRedirect();$this->delete('/goals/'.$g->id)->assertRedirect();$this->assertNotNull($t->fresh());}
 public function test_cross_workspace_goals_habits_tasks_milestones_denied(): void{$u=User::factory()->create();$other=User::factory()->create();$mine=$this->goal($u);$g=$this->goal($other,['title'=>'Foreign private goal']);$h=$this->habit($other);$t=$this->task($other);$m=$g->milestones()->create(['title'=>'Private milestone']);Identity::personal($other)->members()->attach($u->id,['role'=>'admin']);$this->login($u)->get('/goals')->assertOk()->assertDontSee('Foreign private goal');$this->get('/goals/'.$g->id)->assertNotFound();$this->put('/goals/'.$g->id,$this->payload())->assertNotFound();$this->delete('/goals/'.$g->id)->assertNotFound();$this->patch('/goals/'.$mine->id.'/milestones/'.$m->id,['completed'=>1])->assertNotFound();$this->post('/goals/'.$mine->id.'/tasks',['task_id'=>$t->id])->assertSessionHasErrors('task_id');$this->get('/habits/'.$h->id.'/history')->assertNotFound();$this->post('/habits/'.$h->id.'/check',['date'=>'2026-11-27','completed'=>1])->assertNotFound();}
 public function test_business_context_denied(): void{$u=User::factory()->create();$w=Workspace::create(['owner_id'=>$u->id,'name'=>'Business','type'=>'business']);$this->login($u)->withSession(['workspace_id'=>$w->id])->get('/goals')->assertForbidden();$this->get('/habits')->assertForbidden();}
 public function test_habit_crud_and_unique_checkins(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->travelTo(Carbon::parse('2026-11-27 20:00 UTC'));$this->login($u)->post('/habits',['title'=>'Read','active'=>1])->assertRedirect();$h=Habit::firstOrFail();$this->assertSame('2026-11-28',$h->start_date->toDateString());$url='/habits/'.$h->id.'/check';for($i=0;$i<2;$i++)$this->post($url,['date'=>'2026-11-28','completed'=>1])->assertRedirect();$this->assertSame(1,$h->entries()->count());$this->get('/habits')->assertOk()->assertSee('Read');$this->get('/habits/'.$h->id.'/history')->assertOk()->assertSee('2026-11-28');$this->post($url,['date'=>'2026-11-28','completed'=>0])->assertRedirect();$this->assertSame(0,$h->entries()->count());$this->put('/habits/'.$h->id,['title'=>'Read books','active'=>0])->assertRedirect();$this->post($url,['date'=>'2026-11-28','completed'=>1])->assertSessionHasErrors('date');$this->delete('/habits/'.$h->id)->assertRedirect();$this->assertDatabaseMissing('habits',['id'=>$h->id]);}
 public function test_streaks_gaps_and_future_date_validation(): void{$u=User::factory()->create();$h=$this->habit($u);$this->travelTo(Carbon::parse('2026-11-27 10:00 UTC'));$this->login($u);foreach(['2026-11-20','2026-11-21','2026-11-22','2026-11-25','2026-11-26'] as $d)$this->post('/habits/'.$h->id.'/check',['date'=>$d,'completed'=>1])->assertRedirect();$s=app(GoalService::class)->stats($h);$this->assertSame(2,$s['current']);$this->assertSame(3,$s['best']);$this->assertSame(5,$s['total']);foreach(['2026-11-19','2026-11-28'] as $d)$this->post('/habits/'.$h->id.'/check',['date'=>$d,'completed'=>1])->assertSessionHasErrors('date');}
 public function test_review_period_normalization_and_update(): void{$u=User::factory()->create();$this->travelTo(Carbon::parse('2026-11-27 10:00 UTC'));$this->login($u);foreach(['2026-11-24','2026-11-27'] as $d)$this->post('/goals/reviews',['period'=>'week','date'=>$d,'reflection'=>'Weekly reflection'])->assertRedirect();$this->assertSame(1,GoalReview::count());$this->assertSame('2026-11-23',GoalReview::firstOrFail()->period_start->toDateString());$this->post('/goals/reviews',['period'=>'month','date'=>'2026-11-27','reflection'=>'Monthly reflection'])->assertRedirect();$this->assertSame(2,GoalReview::count());$this->get('/goals/reports')->assertOk()->assertSee('Weekly reflection');}
 public function test_vision_and_dashboard_are_private_and_escaped(): void{$u=User::factory()->create();$other=User::factory()->create();$this->goal($other,['title'=>'Hidden goal','vision'=>'Hidden vision']);$this->goal($u,['title'=>'<script>alert(1)</script>']);$this->login($u)->get('/goals/vision')->assertOk()->assertDontSee('Hidden vision')->assertSee('&lt;script&gt;alert(1)&lt;/script&gt;',false)->assertHeader('Cache-Control','no-store, private');$this->get('/dashboard')->assertOk()->assertSee('Active goals')->assertDontSee('Hidden goal');}
}
